"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["68451"],{84411(e){e.exports=JSON.parse('{"id":"F079","slug":"price-elasticity","name":"Price Elasticity of Demand (Midpoint)","subject":"Economics for Finance","section":"How the Economy Works","topic":"Supply, demand and prices","level":"Beginner","aliases":["elasticity","revenue effect of price change","elastic vs inelastic"],"formula":{"latex":"E_{d}=\\\\frac{(Q_{2}-Q_{1})/\\\\bar{Q}}{(P_{2}-P_{1})/\\\\bar{P}},\\\\quad \\\\bar{Q}=\\\\frac{Q_{1}+Q_{2}}{2},\\\\;\\\\bar{P}=\\\\frac{P_{1}+P_{2}}{2}","also":[],"text":"Elasticity = (change in quantity / average quantity) / (change in price / average price). Revenue = price x quantity"},"symbols":[{"symbol":"P_1, P_2","meaning":"Price before and after","unit":"money"},{"symbol":"Q_1, Q_2","meaning":"Quantity demanded before and after","unit":"units"},{"symbol":"E_d","meaning":"Price elasticity of demand. Usually negative; above 1 in size means demand is elastic","unit":"number"}],"when_to_use":"Use it to see how sensitive buyers are to price. If the size of elasticity is above 1, a price rise cuts revenue because volume falls faster. Below 1 (inelastic), a price rise increases revenue. The midpoint method gives the same answer whichever direction the price moves.","worked_example":{"problem":"A price rises from 10 to 12 and the quantity demanded falls from 100 to 88.","inputs":{"p1":10,"q1":100,"p2":12,"q2":88},"steps":[{"label":"Midpoint elasticity","working":"((88-100) / ((100+88) / 2)) / ((12-10) / ((10+12) / 2))","value":"-0.702"},{"label":"Revenue before","working":"10 x 100","value":"1,000.00"},{"label":"Revenue after","working":"12 x 88","value":"1,056.00"},{"label":"Change in revenue","working":"1056 / 1000-1","value":"5.6%"}],"answer":"The elasticity is -0.702. Revenue moves from 1,000.00 to 1,056.00, a change of 5.6%. Because the size of the elasticity is below 1, demand is inelastic and the price rise increased revenue."},"calculator":{"available":true,"inputs":[{"id":"p1","label":"Price before","unit":"money","type":"number","default":10,"hint":""},{"id":"q1","label":"Quantity before","unit":"units","type":"number","default":100,"hint":""},{"id":"p2","label":"Price after","unit":"money","type":"number","default":12,"hint":""},{"id":"q2","label":"Quantity after","unit":"units","type":"number","default":88,"hint":""}],"checks":[{"expr":"p1>0 and p2>0 and p1!=p2 and q1>0 and q2>0","message":"Enter positive prices and quantities, with two different prices."}],"steps":[{"id":"e","label":"Midpoint elasticity","expr":"((q2-q1)/((q1+q2)/2))/((p2-p1)/((p1+p2)/2))","format":"num3"},{"id":"r1","label":"Revenue before","expr":"p1*q1","format":"money"},{"id":"r2","label":"Revenue after","expr":"p2*q2","format":"money"},{"id":"dr","label":"Change in revenue","expr":"r2/r1-1","format":"pct1"}],"results":["e","dr"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"e":-0.702127659574468,"r1":1000,"r2":1056,"dr":0.056}},"finder":{"finds":"How strongly quantity responds to price","needs":"Two price and quantity pairs"},"related":[{"slug":"supply-demand-equilibrium","name":"Linear Supply and Demand Equilibrium"},{"slug":"okun-law","name":"Okun\'s Law"},{"slug":"laspeyres-cpi","name":"Consumer Price Index (Laspeyres) and Substitution Bias"}],"related_ids":["F078","F083","F082"],"group":"Money, banks and the economy","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><msub><mi>E</mi><mi>d</mi></msub><mo>=</mo><mfrac><mrow><mo stretchy=\\"false\\">(</mo><msub><mi>Q</mi><mn>2</mn></msub><mo>\u2212</mo><msub><mi>Q</mi><mn>1</mn></msub><mo stretchy=\\"false\\">)</mo><mi mathvariant=\\"normal\\">/</mi><mover accent=\\"true\\"><mi>Q</mi><mo>\u02C9</mo></mover></mrow><mrow><mo stretchy=\\"false\\">(</mo><msub><mi>P</mi><mn>2</mn></msub><mo>\u2212</mo><msub><mi>P</mi><mn>1</mn></msub><mo stretchy=\\"false\\">)</mo><mi mathvariant=\\"normal\\">/</mi><mover accent=\\"true\\"><mi>P</mi><mo>\u02C9</mo></mover></mrow></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mover accent=\\"true\\"><mi>Q</mi><mo>\u02C9</mo></mover><mo>=</mo><mfrac><mrow><msub><mi>Q</mi><mn>1</mn></msub><mo>+</mo><msub><mi>Q</mi><mn>2</mn></msub></mrow><mn>2</mn></mfrac><mo separator=\\"true\\">,</mo><mtext>\u2005\u200A</mtext><mover accent=\\"true\\"><mi>P</mi><mo>\u02C9</mo></mover><mo>=</mo><mfrac><mrow><msub><mi>P</mi><mn>1</mn></msub><mo>+</mo><msub><mi>P</mi><mn>2</mn></msub></mrow><mn>2</mn></mfrac></mrow><annotation encoding=\\"application/x-tex\\">E_{d}=\\\\frac{(Q_{2}-Q_{1})/\\\\bar{Q}}{(P_{2}-P_{1})/\\\\bar{P}},\\\\quad \\\\bar{Q}=\\\\frac{Q_{1}+Q_{2}}{2},\\\\;\\\\bar{P}=\\\\frac{P_{1}+P_{2}}{2}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"pv-ordinary-annuity","name":"Present Value of an Ordinary Annuity"},"next":{"slug":"price-improvement","name":"Price Improvement (Order Flow)"},"lesson":null,"total":522}')}}]);